function getTitle(title,style){
		if(style==0){
				title = '༺ˇ»`ʚ'+title+'ɞ´«ˇ༻'
			}
		else{
				title = '༺ '+title+' ༻'
			}
		return '{"title":"'+title+'","url":"","style":{"layout_flexBasisPercent":1}},'
	}

function getSort(title,uid){
		url = String(uid).match(/baidu/) ? uid : 'http://101.43.12.135:3200/getSongLists?categoryId=' + uid + '&page={{page}\}'
		return '{"title":"'+title+'","url":"'+url+'","style":{"layout_flexGrow":1}},'
	}


